        private static readonly IReadOnlyDictionary<string, string>[] Catalogs = BuildCatalogs();

        private static IReadOnlyDictionary<string, string>[] BuildCatalogs()
        {
            var catalogs = new IReadOnlyDictionary<string, string>[3];
            for (var language = 0; language < catalogs.Length; language++)
            {
                var dictionary = new Dictionary<string, string>(StringComparer.Ordinal);
                foreach (var row in Rows)
                {
                    if (row.Length != 4 || string.IsNullOrWhiteSpace(row[language + 1]))
                        throw new InvalidOperationException("Missing equivalent research UI translation: " + row[0]);
                    dictionary.Add(row[0], row[language + 1]);
                }
                catalogs[language] = new System.Collections.ObjectModel.ReadOnlyDictionary<string, string>(dictionary);
            }
            return catalogs;
        }

        public static IReadOnlyDictionary<string, string> All(string language)
        {
            if (string.Equals(language, "Thai", StringComparison.OrdinalIgnoreCase) || string.Equals(language, "TH", StringComparison.OrdinalIgnoreCase)) return Catalogs[1];
            if (string.Equals(language, "Japanese", StringComparison.OrdinalIgnoreCase) || string.Equals(language, "JP", StringComparison.OrdinalIgnoreCase) || string.Equals(language, "JA", StringComparison.OrdinalIgnoreCase)) return Catalogs[2];
            return Catalogs[0];
        }

        public static string Get(string key, string language)
        {
            if (key == null) return string.Empty;
            if (All(language).TryGetValue(key, out var value)) return value;
            return Catalogs[0].TryGetValue(key, out value) ? value : key;
        }
    }
